    @Serializable(with = EvidenceGradeOrNoneSerializer::class) val grade: EvidenceGrade? = null,
    /** Backing reference (author/year or DOI). */
    val citation: String = "",
    /** 0.05–0.90 confidence score. */
    val confidence: Float = 0.0f,
