@Serializable(with = EventSerializer::class)
sealed interface Event {

    /** Record one readiness observation, then recompute adjustments. */
    @Serializable
    data class SubmitReadiness(
        val signal: ReadinessSignal,
        val value: Double,
        /** Unix seconds. */
        @SerialName("observed_at") val observedAt: Long,
        /**
         * Duration in minutes of the continuous effort backing this observation,
         * for signals derived from one effort. File 06 signal spec: aerobic
         * decoupling is *valid only for efforts >20 min*, so the downgrade fires
         * only when duration is KNOWN valid. `None`, the wire default, means
         * "duration not tracked": it is not known-valid, so the decoupling signal
         * is discarded (no downgrade), as is an explicitly short effort.
         */
        @SerialName("effort_min") @EncodeDefault(EncodeDefault.Mode.NEVER) val effortMin: Double? = null,
        /**
         * Consecutive days/sessions (including this one) the signal's condition
         * has held, shell-tallied. `0` (the wire default for shells that predate
         * the field) means "not tracked" and is treated like a single observation.
         * Multi-day rules (File 06): e1RM deload needs ≥2 sessions (autoreg-022),
         * RHR downgrade needs ≥2 days (autoreg-040), the SubjectiveMultiDay tier
         * needs ≥3 days of wellness suppression (§5 tier 4).
         */
        val streak: Int = 0,
        /**
         * Pain characterization for `signal == Pain` (File 08 Table 4.1,
         * safety-038/039). `None`, the wire default, keeps the conservative
         * pre-existing behavior: any pain report is a hard stop.
         */
        @EncodeDefault(EncodeDefault.Mode.NEVER) val pain: PainDetail? = null,
    ) : Event

    /**
     * Drop all accumulated inputs (new day / new session). Undated, so it
     * cannot tell which days the dropped inputs shaped: it wipes the active and
     * the retracted inputs alike, and a past day is re-judged without them.
     */
    data object ClearReadiness : Event

    /**
     * Undo for one report: remove the most recent input carrying `signal`
     * (for Pain, the worst active report), leaving unrelated inputs intact.
     * No-op when no such input exists. A dated remove (`observed_at > 0`,
     * unix seconds) retracts the input: gone for today and the future, still
     * in force for any past day before the removal's local day. An undated
     * remove deletes it outright.
     */
    @Serializable
    data class RemoveReadiness(
        val signal: ReadinessSignal,
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
    ) : Event

    /**
     * "I'm better" / "I'm pain-free now": every ACTIVE
     * report of `signal` (Pain or Illness) is retracted as resolved at
     * `observed_at`. History is kept (each moves to `retracted_inputs`, still
     * in force for the past days it shaped) and the coach restarts with a
     * graded return (RETURN-HOLD-001 / ILLNESS-RTT-001). Unlike
     * `RemoveReadiness` it clears every report of that signal (several daily
     * "still ill" answers belong to one episode) and never touches other
     * signals. `observed_at <= 0` is a no-op: a resolution must be dated.
     */
    @Serializable
    data class ResolveHold(
        val signal: ReadinessSignal,
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
    ) : Event

    /**
     * Record one morning check-in (raw human observations). Appended to the
     * RETAINED check-in history the core normalizes into z-scores/deltas;
     * unlike `SubmitReadiness`, this is not day-cleared.
     */
    @Serializable
    data class SubmitCheckin(
        /**
         * Unix seconds, shell-supplied (the core holds no clock). Day-buckets the
         * rolling baseline; `<= 0` readings are ignored by the derivation.
         */
        @SerialName("observed_at") val observedAt: Long = 0L,
        /** Sleep quality, 1–5 (5 = slept great). Higher = better. */
        @SerialName("sleep_quality") @EncodeDefault(EncodeDefault.Mode.NEVER) val sleepQuality: Int? = null,
        /**
         * Muscle soreness today, 1–5 (5 = very sore). Higher = worse, the core
         * reverse-scores it into the "higher = better" wellness composite.
         */
        @EncodeDefault(EncodeDefault.Mode.NEVER) val soreness: Int? = null,
        /**
         * Mood / motivation, 1–5 (5 = great mood). Higher = better. Perceived stress
         * is a SEPARATE item (`stress`), not folded in here.
         */
        @EncodeDefault(EncodeDefault.Mode.NEVER) val mood: Int? = null,
        /**
         * Fatigue today, 1–5 (5 = utterly wiped). Higher = worse (same direction as
         * soreness); the core reverse-scores it into the "higher = better" wellness
         * composite. KB 5-item short-form item (autoreg WellnessZ).
         */
        @EncodeDefault(EncodeDefault.Mode.NEVER) val fatigue: Int? = null,
        /**
         * Perceived stress today, 1–5 (5 = extremely stressed). Higher = worse; the
         * core reverse-scores it. Distinct from `mood` (affect/motivation, scored in
         * the good direction). KB 5-item short-form item (autoreg WellnessZ).
         */
        @EncodeDefault(EncodeDefault.Mode.NEVER) val stress: Int? = null,
        /**
         * Morning resting HR, bpm (from a watch/manual pulse). The core computes
         * the vs-baseline delta the RHR rules read (autoreg-040/041).
         */
        @SerialName("resting_hr_bpm") @EncodeDefault(EncodeDefault.Mode.NEVER) val restingHrBpm: Double? = null,
        /**
         * Morning HRV as raw rMSSD in ms (from a watch/app). The core takes
         * `ln(rmssd)` and the rolling-baseline z the HRV rule reads (autoreg-028).
         */
        @SerialName("hrv_rmssd_ms") @EncodeDefault(EncodeDefault.Mode.NEVER) val hrvRmssdMs: Double? = null,
    ) : Event

    /**
     * Drop the entire check-in history (part of "Clear all data"). Not tied to
     * `ClearReadiness`, the two stores have different lifecycles.
     */
    data object ClearCheckins : Event

    /**
     * "Changed device? Restart HRV baseline" (HRV-SOURCE-001: one
     * HRV source and timing, never mixed): every HRV reading logged before
     * `observed_at` is ignored from now on, so the baseline rebuilds from the
     * new source. Only HRV is affected; the other check-in items stay. The
     * latest restart wins; `ClearCheckins` also resets it.
     */
    @Serializable
    data class RestartHrvBaseline(
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
    ) : Event

    /** Log one completed lift set (weight in kg, reps, session RPE). */
    @Serializable
    data class LogSet(
        val exercise: String,
        @SerialName("weight_kg") val weightKg: Double,
        val reps: Int,
        val rpe: Double,
        /**
         * When the set was logged, unix seconds; shell-supplied (the core holds
         * no clock). 0 = undated.
         */
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
        /**
         * Stable per-entry id: a shell-assigned monotonic value
         * (epoch-millis at log) so `AmendSet`/`DeleteEntry` can target this exact
         * set. 0 = no id (matched on `observed_at` instead).
         */
        @SerialName("entry_id") val entryId: Long = EntryIds.next(),
        /**
         * Timed-hold duration, seconds — `Some` for a static/hold set (a
         * calisthenics lever/plank/dead-hang rung), `None` for a reps×load set.
         */
        @SerialName("hold_sec") @EncodeDefault(EncodeDefault.Mode.NEVER) val holdSec: Int? = null,
    ) : Event

    /** Drop all logged sets. */
    data object ClearSets : Event

    /**
     * Mark a plan exercise ended early for a session day, or reopen it.
     * Last-write-wins per `rules::end_marker_key` (movement, `epoch_day`);
     * `ended: false` reopens. An ended item is done regardless of logged sets,
     * so the shell's "End exercise" / "Reopen" action drives it. Persisted;
     * `ClearSets` clears every ended marker.
     */
    @Serializable
    data class SetExerciseEnded(
        val exercise: String,
        @SerialName("epoch_day") val epochDay: Long,
        val ended: Boolean,
        /** When the marker was set, unix seconds (shell clock); 0 = undated. */
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
    ) : Event

    /**
     * Log one run (distance km, duration min, average % HRmax, and the
     * longest run in the last 30 days for spike detection).
     */
    @Serializable
    data class LogRun(
        @SerialName("distance_km") val distanceKm: Double,
        @SerialName("duration_min") val durationMin: Double,
        @SerialName("hr_pct_max") val hrPctMax: Double,
        @SerialName("longest_recent_km") val longestRecentKm: Double = 0.0,
        /** Log time, unix seconds; shell-supplied, 0 = undated. */
        @SerialName("observed_at") val observedAt: Long = AppClock.nowSec(),
        /**
         * User-declared run-intent label. USER DATA with no evidence of its
         * own: the weekly report's hard-session checks honor it as the
         * session's declared goal (running-012/023). `None` = untagged.
         */
        @SerialName("workout_type") @EncodeDefault(EncodeDefault.Mode.NEVER) val workoutType: WorkoutType? = null,
        /**
         * Whole-session effort on the CR-10 scale (0–10), rated ~30 min after
         * the run (LOAD-SRPE-001). `None` = unrated; values above 10 clamp to
         * 10 at ingest.
         */
        @SerialName("session_rpe") @EncodeDefault(EncodeDefault.Mode.NEVER) val sessionRpe: Int? = null,
        /**
         * Average heart rate in bpm as the user's watch shows it (UXL-12). When
         * set and plausible, `update` converts it to `hr_pct_max` against the
         * measured HRmax, else the Tanaka age estimate (RUN-HRMAX-001), of the
         * profile in force at the run's instant (re-derived when the profile
         * history changes); with neither known the sent `hr_pct_max` stands.
         */
        @SerialName("avg_hr_bpm") @EncodeDefault(EncodeDefault.Mode.NEVER) val avgHrBpm: Double? = null,
        /** Stable per-entry id; see [`Event::LogSet`]. */
        @SerialName("entry_id") val entryId: Long = EntryIds.next(),
        /**
         * The device's UTC offset, seconds east, when the run was logged. The
         * bpm conversion reads the run's local day with it, so a later
         * time-zone change never re-converts the run. `None` (omitted from the
         * wire) = the clock's current offset.
         */
        @SerialName("utc_offset_sec") @EncodeDefault(EncodeDefault.Mode.NEVER) val utcOffsetSec: Long? = null,
    ) : Event

    /**
     * Log one GPS-tracked run. Distance and duration are derived in-core from
     * the fix track (haversine + time span); `hr_pct_max` comes from a paired
