    @Serializable
    data class ComputeHrZones(
        @SerialName("age_years") val ageYears: Double,
        @SerialName("resting_hr_bpm") @EncodeDefault(EncodeDefault.Mode.NEVER) val restingHrBpm: Double? = null,
    ) : Event

    /** Drop the heart-rate-zone table (clears the zone section). */
    data object ClearHrZones : Event

    /**
