    @Serializable
    data class GeneratePlan(
        @SerialName("start_epoch_day") val startEpochDay: Long,
    ) : Event

    /** Drop the plan (Coach returns to no-plan state). */
    data object ClearPlan : Event

    /**
     * The shell's clock as event data: today's LOCAL epoch-day, sent
     * on foreground so `view()` dates the week + picks the next session with no
     * clock in-core. Last-write-wins singleton (compaction keeps one line).
     * `utc_offset_sec` is the device's offset east of UTC (0 = UTC), which
     * buckets every UTC `observed_at` into a local day (`crate::day::local_day`).
     */
    @Serializable
    data class SetToday(
        @SerialName("epoch_day") val epochDay: Long,
        @SerialName("utc_offset_sec") val utcOffsetSec: Long = 0L,
    ) : Event

    /**
     * Place a calisthenics ladder at a rung (CAL-PLACE-001): the starting rung
     * chosen in setup, or an Easier / Harder choice on a plan item. Applies
     * from its own local day on (that day's prescription included); sets
     * logged afterwards drive the ladder as usual. A rung index past the
     * ladder's end is ignored. Wire:
     * `{"SetCalisthenicsRung":{"ladder":"HorizontalPush","rung":4,"observed_at":1759700000}}`.
     */
    @Serializable
    data class SetCalisthenicsRung(
        val ladder: LadderId,
        val rung: Int,
        /**
         * Unix seconds (shell clock); 0 = undated (applies from the start of
         * history).
         */
        @SerialName("observed_at") val observedAt: Long = 0L,
    ) : Event

    /**
     * Move one planned session to another day of the same plan week
     * (ADH-RESCHED-001): a missed day's session made up later, or a later
     * session pulled forward to today. `to_epoch_day` must be a rest day;
     * the move is refused (left out of the plan, with a reason in
     * `SessionPlanView::move_note`) when it would put two sessions on one day,
     * leave under ~48 h between hard sessions, or bring a hard/long run within
     * 24 h of heavy leg work. Wire:
     * `{"MoveSession":{"from_epoch_day":20360,"to_epoch_day":20361}}`.
     */
    @Serializable
    data class MoveSession(
        @SerialName("from_epoch_day") val fromEpochDay: Long,
        @SerialName("to_epoch_day") val toEpochDay: Long,
    ) : Event

    companion object
}

private val EventUnitTags = setOf("ClearReadiness", "ClearCheckins", "ClearSets", "ClearRuns", "ClearActivities", "ClearProfile", "ClearReview", "ClearWeeklyCheckin", "ClearRacePrediction", "ClearHypertrophyPlan", "ClearProtein", "ClearHrZones", "ClearPlan")

private val EventPayloadTags = setOf("SubmitReadiness", "RemoveReadiness", "ResolveHold", "SubmitCheckin", "RestartHrvBaseline", "LogSet", "SetExerciseEnded", "LogRun", "LogRunTrack", "LogActivity", "DeleteEntry", "AmendSet", "AmendRun", "TrimRunTrack", "AmendRunMeta", "SetProfile", "SubmitReview", "SubmitWeeklyCheckin", "PredictRace", "PlanHypertrophyMeso", "ComputeProtein", "ComputeHrZones", "GeneratePlan", "SetToday", "SetCalisthenicsRung", "MoveSession")

/** The wire tag of `element` when it is a [Event] in a shape serde accepts
 * (a unit variant's bare string, a payload variant's single-key object), else null. */
fun Event.Companion.tagOf(element: JsonElement): String? = when (element) {
    is JsonPrimitive -> element.content.takeIf { element.isString && it in EventUnitTags }
    is JsonObject -> element.keys.singleOrNull()?.takeIf { it in EventPayloadTags && element[it] is JsonObject }
    else -> null
}

/** [Event] in serde's external tagging. */
internal object EventSerializer : KSerializer<Event> {
    override val descriptor: SerialDescriptor = SerialDescriptor("app.milestone.Event", JsonElement.serializer().descriptor)

    override fun serialize(encoder: Encoder, value: Event) {
        val json = (encoder as JsonEncoder).json
        encoder.encodeJsonElement(
            when (value) {
                is Event.SubmitReadiness -> JsonObject(mapOf("SubmitReadiness" to json.encodeToJsonElement(Event.SubmitReadiness.serializer(), value)))
                Event.ClearReadiness -> JsonPrimitive("ClearReadiness")
                is Event.RemoveReadiness -> JsonObject(mapOf("RemoveReadiness" to json.encodeToJsonElement(Event.RemoveReadiness.serializer(), value)))
                is Event.ResolveHold -> JsonObject(mapOf("ResolveHold" to json.encodeToJsonElement(Event.ResolveHold.serializer(), value)))
                is Event.SubmitCheckin -> JsonObject(mapOf("SubmitCheckin" to json.encodeToJsonElement(Event.SubmitCheckin.serializer(), value)))
                Event.ClearCheckins -> JsonPrimitive("ClearCheckins")
                is Event.RestartHrvBaseline -> JsonObject(mapOf("RestartHrvBaseline" to json.encodeToJsonElement(Event.RestartHrvBaseline.serializer(), value)))
                is Event.LogSet -> JsonObject(mapOf("LogSet" to json.encodeToJsonElement(Event.LogSet.serializer(), value)))
                Event.ClearSets -> JsonPrimitive("ClearSets")
                is Event.SetExerciseEnded -> JsonObject(mapOf("SetExerciseEnded" to json.encodeToJsonElement(Event.SetExerciseEnded.serializer(), value)))
                is Event.LogRun -> JsonObject(mapOf("LogRun" to json.encodeToJsonElement(Event.LogRun.serializer(), value)))
                is Event.LogRunTrack -> JsonObject(mapOf("LogRunTrack" to json.encodeToJsonElement(Event.LogRunTrack.serializer(), value)))
                Event.ClearRuns -> JsonPrimitive("ClearRuns")
                is Event.LogActivity -> JsonObject(mapOf("LogActivity" to json.encodeToJsonElement(Event.LogActivity.serializer(), value)))
                Event.ClearActivities -> JsonPrimitive("ClearActivities")
                is Event.DeleteEntry -> JsonObject(mapOf("DeleteEntry" to json.encodeToJsonElement(Event.DeleteEntry.serializer(), value)))
                is Event.AmendSet -> JsonObject(mapOf("AmendSet" to json.encodeToJsonElement(Event.AmendSet.serializer(), value)))
                is Event.AmendRun -> JsonObject(mapOf("AmendRun" to json.encodeToJsonElement(Event.AmendRun.serializer(), value)))
                is Event.TrimRunTrack -> JsonObject(mapOf("TrimRunTrack" to json.encodeToJsonElement(Event.TrimRunTrack.serializer(), value)))
                is Event.AmendRunMeta -> JsonObject(mapOf("AmendRunMeta" to json.encodeToJsonElement(Event.AmendRunMeta.serializer(), value)))
                is Event.SetProfile -> JsonObject(mapOf("SetProfile" to json.encodeToJsonElement(Event.SetProfile.serializer(), value)))
                Event.ClearProfile -> JsonPrimitive("ClearProfile")
                is Event.SubmitReview -> JsonObject(mapOf("SubmitReview" to json.encodeToJsonElement(Event.SubmitReview.serializer(), value)))
                Event.ClearReview -> JsonPrimitive("ClearReview")
                is Event.SubmitWeeklyCheckin -> JsonObject(mapOf("SubmitWeeklyCheckin" to json.encodeToJsonElement(Event.SubmitWeeklyCheckin.serializer(), value)))
                Event.ClearWeeklyCheckin -> JsonPrimitive("ClearWeeklyCheckin")
                is Event.PredictRace -> JsonObject(mapOf("PredictRace" to json.encodeToJsonElement(Event.PredictRace.serializer(), value)))
                Event.ClearRacePrediction -> JsonPrimitive("ClearRacePrediction")
                is Event.PlanHypertrophyMeso -> JsonObject(mapOf("PlanHypertrophyMeso" to json.encodeToJsonElement(Event.PlanHypertrophyMeso.serializer(), value)))
                Event.ClearHypertrophyPlan -> JsonPrimitive("ClearHypertrophyPlan")
                is Event.ComputeProtein -> JsonObject(mapOf("ComputeProtein" to json.encodeToJsonElement(Event.ComputeProtein.serializer(), value)))
                Event.ClearProtein -> JsonPrimitive("ClearProtein")
                is Event.ComputeHrZones -> JsonObject(mapOf("ComputeHrZones" to json.encodeToJsonElement(Event.ComputeHrZones.serializer(), value)))
                Event.ClearHrZones -> JsonPrimitive("ClearHrZones")
                is Event.GeneratePlan -> JsonObject(mapOf("GeneratePlan" to json.encodeToJsonElement(Event.GeneratePlan.serializer(), value)))
                Event.ClearPlan -> JsonPrimitive("ClearPlan")
                is Event.SetToday -> JsonObject(mapOf("SetToday" to json.encodeToJsonElement(Event.SetToday.serializer(), value)))
                is Event.SetCalisthenicsRung -> JsonObject(mapOf("SetCalisthenicsRung" to json.encodeToJsonElement(Event.SetCalisthenicsRung.serializer(), value)))
                is Event.MoveSession -> JsonObject(mapOf("MoveSession" to json.encodeToJsonElement(Event.MoveSession.serializer(), value)))
            },
        )
    }

    override fun deserialize(decoder: Decoder): Event {
        val input = decoder as JsonDecoder
        val element = input.decodeJsonElement()
        val tag = Event.tagOf(element) ?: throw SerializationException("not a Event: $element")
        if (element is JsonPrimitive) {
            return when (tag) {
                "ClearReadiness" -> Event.ClearReadiness
                "ClearCheckins" -> Event.ClearCheckins
                "ClearSets" -> Event.ClearSets
                "ClearRuns" -> Event.ClearRuns
                "ClearActivities" -> Event.ClearActivities
                "ClearProfile" -> Event.ClearProfile
                "ClearReview" -> Event.ClearReview
                "ClearWeeklyCheckin" -> Event.ClearWeeklyCheckin
                "ClearRacePrediction" -> Event.ClearRacePrediction
                "ClearHypertrophyPlan" -> Event.ClearHypertrophyPlan
                "ClearProtein" -> Event.ClearProtein
                "ClearHrZones" -> Event.ClearHrZones
                "ClearPlan" -> Event.ClearPlan
                else -> throw SerializationException("not a Event: $element")
            }
        }
        val payload = (element as JsonObject).getValue(tag)
        return when (tag) {
            "SubmitReadiness" -> input.json.decodeFromJsonElement(Event.SubmitReadiness.serializer(), payload)
            "RemoveReadiness" -> input.json.decodeFromJsonElement(Event.RemoveReadiness.serializer(), payload)
            "ResolveHold" -> input.json.decodeFromJsonElement(Event.ResolveHold.serializer(), payload)
            "SubmitCheckin" -> input.json.decodeFromJsonElement(Event.SubmitCheckin.serializer(), payload)
            "RestartHrvBaseline" -> input.json.decodeFromJsonElement(Event.RestartHrvBaseline.serializer(), payload)
            "LogSet" -> input.json.decodeFromJsonElement(Event.LogSet.serializer(), payload)
            "SetExerciseEnded" -> input.json.decodeFromJsonElement(Event.SetExerciseEnded.serializer(), payload)
            "LogRun" -> input.json.decodeFromJsonElement(Event.LogRun.serializer(), payload)
            "LogRunTrack" -> input.json.decodeFromJsonElement(Event.LogRunTrack.serializer(), payload)
            "LogActivity" -> input.json.decodeFromJsonElement(Event.LogActivity.serializer(), payload)
            "DeleteEntry" -> input.json.decodeFromJsonElement(Event.DeleteEntry.serializer(), payload)
            "AmendSet" -> input.json.decodeFromJsonElement(Event.AmendSet.serializer(), payload)
            "AmendRun" -> input.json.decodeFromJsonElement(Event.AmendRun.serializer(), payload)
            "TrimRunTrack" -> input.json.decodeFromJsonElement(Event.TrimRunTrack.serializer(), payload)
            "AmendRunMeta" -> input.json.decodeFromJsonElement(Event.AmendRunMeta.serializer(), payload)
            "SetProfile" -> input.json.decodeFromJsonElement(Event.SetProfile.serializer(), payload)
            "SubmitReview" -> input.json.decodeFromJsonElement(Event.SubmitReview.serializer(), payload)
            "SubmitWeeklyCheckin" -> input.json.decodeFromJsonElement(Event.SubmitWeeklyCheckin.serializer(), payload)
            "PredictRace" -> input.json.decodeFromJsonElement(Event.PredictRace.serializer(), payload)
            "PlanHypertrophyMeso" -> input.json.decodeFromJsonElement(Event.PlanHypertrophyMeso.serializer(), payload)
            "ComputeProtein" -> input.json.decodeFromJsonElement(Event.ComputeProtein.serializer(), payload)
            "ComputeHrZones" -> input.json.decodeFromJsonElement(Event.ComputeHrZones.serializer(), payload)
            "GeneratePlan" -> input.json.decodeFromJsonElement(Event.GeneratePlan.serializer(), payload)
            "SetToday" -> input.json.decodeFromJsonElement(Event.SetToday.serializer(), payload)
            "SetCalisthenicsRung" -> input.json.decodeFromJsonElement(Event.SetCalisthenicsRung.serializer(), payload)
            "MoveSession" -> input.json.decodeFromJsonElement(Event.MoveSession.serializer(), payload)
            else -> throw SerializationException("not a Event: $element")
        }
    }
}

/** A characterized pain report attached to a `Pain` readiness input. */
@Serializable
data class PainDetail(
    val kind: PainKind,
    /**
     * 0–10 numeric rating scale. Tendon tolerable band ≤5/10 (safety-039).
     * `None` = the user gave no rating; graded conservatively (outside the
     * tolerable band). Old logs carrying a bare number decode to `Some`.
     */
    @EncodeDefault(EncodeDefault.Mode.NEVER) val severity: Int? = null,
    val trend: PainTrend,
    /**
     * True when the pain has persisted across sessions despite modification -
     * escalates STOP/REDUCE responses to DEFER (safety-038/039 "if persists").
     */
    val persists: Boolean = false,
    /**
     * Free-text body-part location (e.g. `"Left knee"`) for display context on
     * the safety banner sub-line and pain history. For a non-persisting
     * sharp/joint report it also scopes the stop: a location that maps to one
     * body region stops only the movements that load it (File 08 safety-038
     * "STOP that exercise"); anything unmapped keeps the
     * whole-day stop. `None`, the wire default, keeps every existing log
     * replaying unchanged (whole-day stop, no body part on the sub-line).
     */
    @EncodeDefault(EncodeDefault.Mode.NEVER) val location: String? = null,
)

/** Pain character/context per File 08 Table 4.1 (Silbernagel monitoring model). */
@Serializable
enum class PainKind {
    /**
     * Sharp, localized, or joint-line pain; alters movement/gait; or occurs
     * with swelling → possible structural injury (safety-038). Hard stop.
     */
    SharpJoint,
    /**
     * Load-related tendon pain → graded by severity/trend per the Silbernagel
     * pain-monitoring model (safety-039). "Avoid complete rest."
     */
    TendonLoadRelated,
    /**
     * Muscle burn during a set / DOMS 24–72 h easing with movement → normal
     * training discomfort; continue.
     */
    Doms,
    /** Uncharacterized pain → conservative hard stop (same as a bare report). */
    Other,
    ;

    /** The wire string. */
    val wire: String
        get() = when (this) {
            SharpJoint -> "SharpJoint"
            TendonLoadRelated -> "TendonLoadRelated"
            Doms -> "Doms"
            Other -> "Other"
        }
}

/** Week-to-week / post-session pain trajectory (File 08 Table 4.1). */
@Serializable
enum class PainTrend {
    /** Stable during & 24 h after; returns to baseline next morning. */
    Stable,
    /** Worsening after sessions or rising week-to-week → reactive. */
    Rising,
    /**
     * Pain that worsens in the 24 h AFTER load even if stable during → reactive
     * (Silbernagel monitoring, File 08 Table 4.1). Treated like `Rising`.
     */
    WorseningAfter24h,
    ;

    /** The wire string. */
    val wire: String
        get() = when (this) {
            Stable -> "Stable"
            Rising -> "Rising"
            WorseningAfter24h -> "WorseningAfter24h"
        }
}

/**
 * One GPS fix from a run track. Deterministic core input: wall-clock time
 * enters only as `observed_at` (unix seconds), never a live clock. Lat/lon in
 * decimal degrees; `accuracy_m` is the shell provider's reported horizontal
 * error, used to drop noisy fixes before summing distance.
 */
@Serializable
data class GpsPoint(
    val lat: Double,
    val lon: Double,
    @SerialName("observed_at") val observedAt: Long,
    @SerialName("accuracy_m") val accuracyM: Double,
)

/**
 * Which logged history a [`Event::DeleteEntry`] targets: the model's
 * `sets`, `runs` or `activities`.
 */
@Serializable
enum class EntryKind {
    Set,
    Run,
    Activity,
    ;

    /** The wire string. */
    val wire: String
        get() = when (this) {
            Set -> "Set"
            Run -> "Run"
            Activity -> "Activity"
        }
}

/**
 * The four overtraining signs the weekly check-in asks about (feedback-036:
 * performance decrement, mood disturbance, elevated resting HR / suppressed
 * HRV, sleep deterioration). When a check-in carries this, the signal count
 * IS the number of signs ticked (it overrides the bare
 * `overtraining_signal_count`), so "a sign" always means one of these four.
 */
@Serializable
data class OvertrainingSigns(
    @SerialName("worse_performance") val worsePerformance: Boolean = false,
    @SerialName("low_mood") val lowMood: Boolean = false,
    @SerialName("higher_resting_hr") val higherRestingHr: Boolean = false,
    @SerialName("worse_sleep") val worseSleep: Boolean = false,
)

/** Lifting-set execution context for post-session feedback. */
@Serializable
data class LiftExec(
    @SerialName("reps_met") val repsMet: Boolean,
    @SerialName("rir_actual") val rirActual: Int,
    @SerialName("rir_target") val rirTarget: Int,
)

/**
 * Interval/threshold-session execution context (feedback-015): did every rep
 * hit its target pace, and did the session cost at or below the target RPE.
 */
@Serializable
data class IntervalExec(
    @SerialName("target_paces_met") val targetPacesMet: Boolean,
    @SerialName("rpe_at_or_below_target") val rpeAtOrBelowTarget: Boolean,
)

/** Aerobic-decoupling context for a run's feedback. */
@Serializable
data class Decouple(
    @SerialName("drift_pct") val driftPct: Double,
    /** Only cool, steady, sub-threshold efforts get a decoupling verdict. */
    @SerialName("cool_steady_context") val coolSteadyContext: Boolean,
)

/**
 * Which way a measured change went: a rolling multi-week metric versus
 * day-to-day noise, or one set's e1RM versus the previous (wire: lowercase).
 * Any unknown wire value reads as `Flat`, the no-trend default.
 */
@Serializable(with = TrendDirectionSerializer::class)
enum class TrendDirection {
    Up,
    Down,
    Flat,
    ;

    /** The wire string. */
    val wire: String
        get() = when (this) {
            Up -> "up"
            Down -> "down"
            Flat -> "flat"
        }
}

internal object TrendDirectionSerializer : KSerializer<TrendDirection> {
    override val descriptor = PrimitiveSerialDescriptor("app.milestone.TrendDirection", PrimitiveKind.STRING)

    override fun serialize(encoder: Encoder, value: TrendDirection) = encoder.encodeString(value.wire)

    override fun deserialize(decoder: Decoder): TrendDirection {
        val wire = decoder.decodeString()
        return TrendDirection.entries.firstOrNull { it.wire == wire } ?: TrendDirection.Flat
    }
}

/**
 * `{"error":{…}}`: `error` is the only top-level key, so an envelope is never
 * mistaken for an effect-request array, a `ViewModel` or any op's payload.
 */
@Serializable
data class ErrorEnvelope(
    val error: CoreError = CoreError(),
)

/** One failed op: the body of `{"error":{"kind":K,"context":C,"message":M}}`. */
@Serializable
data class CoreError(
    val kind: ErrorKind = ErrorKind.PanicReset,
    val context: String = "",
    val message: String = "",
)

/**
 * Why an op answered an [`ErrorEnvelope`]; serialised as the envelope's
 * `kind`. The shell keys on `panic_reset` (replay the log into the fresh
 * core) and on the FIT kinds (per-file import reason); any other kind reads
 * as a generic failure.
 */
@Serializable
enum class ErrorKind {
    /** A core panic on the update path; the core was replaced with an empty one. */
    @SerialName("panic_reset")
    PanicReset,
    /** A core panic that left the core intact. */
    @SerialName("panic")
    Panic,
    /** The answer could not be serialised. */
    @SerialName("unserializable")
    Unserializable,
    /** The shell's input is not what the op takes. */
    @SerialName("bad_input")
    BadInput,
    /** `FitError::NotFit`. */
    @SerialName("not_fit")
    NotFit,
    /** `FitError::Damaged`. */
    @SerialName("damaged")
    Damaged,
    /** `FitError::NoTrack`. */
    @SerialName("no_track")
    NoTrack,
    /** `FitError::TooShort`. */
    @SerialName("too_short")
    TooShort,
    /** `FitError::NotARun` (context: the sport). */
    @SerialName("not_a_run")
    NotARun,
    ;

    /** The wire string. */
    val wire: String
        get() = when (this) {
            PanicReset -> "panic_reset"
            Panic -> "panic"
            Unserializable -> "unserializable"
            BadInput -> "bad_input"
            NotFit -> "not_fit"
            Damaged -> "damaged"
            NoTrack -> "no_track"
            TooShort -> "too_short"
            NotARun -> "not_a_run"
        }
}

/**
 * The run the GPX export reads, by the `(entry_id, observed_at)` identity
 * the delete/amend matcher uses.
 */
@Serializable
data class RunRef(
    @SerialName("entry_id") val entryId: Long,
    @SerialName("observed_at") val observedAt: Long,
)

/** The distance and moving time a `LogRunTrack` will be saved with. */
@Serializable
data class TrackFigures(
    val distance_km: Double = 0.0,
    val duration_min: Double = 0.0,
)

/** [`compact_lines`]' verdict on a raw log, by line index. */
@Serializable
data class Compaction(
    /** Lines compaction drops, ascending. */
    val dropped: List<Int> = emptyList(),
    /** Lines that are not JSON (a tail torn by a kill mid-append), ascending. */
    val torn: List<Int> = emptyList(),
    /**
     * The largest `entry_id` any intact line carries, kept or not (0 when
     * none), so a shell never reuses one.
     */
    val max_entry_id: Long = 0L,
    /** The last surviving plan line is a `ClearPlan`: the user removed their plan. */
    val plan_removed: Boolean = false,
)

/**
 * A parsed FIT activity: fixes grouped into segments by the recorder's
 * timer stop_all/start events (see [`parse_fit`] for the exact split rule).
 */
@Serializable
data class FitTrack(
    val segments: List<List<FitFix>> = emptyList(),
)

/**
 * One GPS+HR fix extracted from a FIT `record` message. Its serialization is
 * the per-fix wire shape of the `ParseFit` bridge op's payload.
 */
@Serializable
data class FitFix(
    val lat: Double = 0.0,
    val lon: Double = 0.0,
    val time_sec: Long = 0L,
    @EncodeDefault(EncodeDefault.Mode.NEVER) val hr_bpm: Int? = null,
    /**
     * Horizontal position accuracy in metres from the FIT `record.gps_accuracy`
     * field (field 31, `UInt8`, scale 1). `None` when the file has no such
     * field; the shell picks the accuracy it hands the core's QC gate for a
     * `None` fix (`Gpx.kt`'s `importedRunEvent`).
     */
    @EncodeDefault(EncodeDefault.Mode.NEVER) val accuracy_m: Float? = null,
)

/** `EvidenceGrade?` written as the variant's wire string, or "" for null. */
internal object EvidenceGradeOrNoneSerializer : KSerializer<EvidenceGrade?> {
    override val descriptor = PrimitiveSerialDescriptor("app.milestone.EvidenceGradeOrNone", PrimitiveKind.STRING)

    override fun serialize(encoder: Encoder, value: EvidenceGrade?) = encoder.encodeString(value?.wire ?: "")

    override fun deserialize(decoder: Decoder): EvidenceGrade? {
        val wire = decoder.decodeString()
        if (wire == "") return null
        return EvidenceGrade.entries.firstOrNull { it.wire == wire }
            ?: throw SerializationException("unknown EvidenceGrade $wire")
    }
}

/** `ThreeZone?` written as the variant's wire string, or "-" for null. */
internal object ThreeZoneOrNoneSerializer : KSerializer<ThreeZone?> {
    override val descriptor = PrimitiveSerialDescriptor("app.milestone.ThreeZoneOrNone", PrimitiveKind.STRING)

    override fun serialize(encoder: Encoder, value: ThreeZone?) = encoder.encodeString(value?.wire ?: "-")

    override fun deserialize(decoder: Decoder): ThreeZone? {
        val wire = decoder.decodeString()
        if (wire == "-") return null
        return ThreeZone.entries.firstOrNull { it.wire == wire }
            ?: throw SerializationException("unknown ThreeZone $wire")
    }
}
